// === stok.js ===
const daftar = { kopi: 12, teh: 0 };
function cekStok(menu) {
  return daftar[menu] ?? 0;
}
function tersedia(menu) {
  return cekStok(menu) > 0;
}
export { cekStok, tersedia };
// === main.js ===
import { tersedia, cekStok } from "./stok.js";
console.log(tersedia("kopi"), tersedia("teh"));
console.log(cekStok("roti"));

