cards.solution:
// === format.js ===
function rupiah(n) {
  return "Rp" + n.toLocaleString("id-ID");
}
function persen(n) {
  return n * 100 + "%";
}
export { rupiah, persen };
// === main.js ===
import { rupiah, persen } from "./format.js";
console.log(rupiah(1500000));
console.log(persen(0.25));
